Lemma schunk_nw : forall W k s (m m' : mem), schunk k s m -> munch W m m' -> schunk_avoid W s ->
  disjoint_from W (s_mb s) (smsz (s_n s)) -> disjoint_from W (shad (s_mb s)) (shad (s_mb s + smsz (s_n s)) - shad (s_mb s)) ->
  schunk k s m'.
